 p=H/('work-source-v1.png' if role=='work' else 'pickup-source-v2.png');prompt=H/('work-prompt-v1.txt' if role=='work' else 'pickup-prompt-v2.txt');im=Image.open(p)
 sources.append(dict(source=p.relative_to(R).as_posix(),sha256=sha(p),dimensions=list(im.size),mode=im.mode,prompt=prompt.relative_to(R).as_posix(),promptSha256=sha(prompt),builtinOriginal='C:/Users/Alex/.codex/generated_images/01a0ef89-9984-7e73-99c2-84cdd8b28b14/'+original,references=[dict(path=x.relative_to(R).as_posix(),sha256=sha(x)) for x in refs],selection='all six work poses' if role=='work' else 'interiors1..4; endpoints replaced by exact fitted work/cargo authority'))
