html='''<!doctype html><meta charset="utf-8"><title>Veld west underwater sample work and pickup</title><style>body{background:#202a30;color:#e5ebed;font:16px sans-serif;margin:24px}canvas,img{max-width:100%;height:auto}button,select,input{margin:8px}a{color:#8cc6e7}</style><h1>Veld — west sample work and pickup</h1><p>Matte master-based sample work, probe stow and two-hand case lift. Same anatomical ruler, material curves and closed helmet as cargo. Staged; controller phase offsets and world journeys remain.</p><label>Clip <select id="clip"><option value="salvage-west">Sample work · 840ms</option><option value="swim-pickup-west">Pickup · 520ms</option><option value="chain">Work → pickup → cargo</option></select></label><button id="play">Pause</button><label>Frame <input id="phase" aria-label="Frame" type="range" min="0" max="5" value="0"></label><label>Speed <select id="speed"><option value="1">Full speed</option><option value="0.3333333333">One-third speed</option></select></label><label>Background <select id="bg"><option value="#202a30">Dark</option><option value="#a7afb2">Light</option></select></label><span id="clock"></span><canvas id="canvas" width="1024" height="700"></canvas><p><a href="paired-full-speed-chain-v1.mp4">Full-speed work/pickup/cargo sequence</a> · <a href="paired-contact-v1.png">Every authored phase</a> · <a href="source-provenance.json">Raw sources and prompts</a></p><h2>Selected swim / work / pickup / cargo master</h2><img src="master-comparison-v1.png"><script>const data=DATA;let phase=0,elapsed=0,last=performance.now(),running=true;const ctx=canvas.getContext('2d'),images={};async function init(){for(const g of ['bare','helmet']){images[g]={};for(const s of data[g].states){images[g][s.id]=await Promise.all(s.frameFiles.map(url=>new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(im);im.src=url})))}images[g].cargo=[await new Promise(resolve=>{const im=new Image();im.onload=()=>resolve(im);im.src='../veld-swim-carry-west-coherent-v1/frames/'+g+'/swim-carry-west/000.png'})]}requestAnimationFrame(tick)}function selection(){let key=clip.value,e=elapsed;if(key==='chain'){if(e<840)key='salvage-west';else if(e<1360){key='swim-pickup-west';e-=840}else return ['cargo',0]}const s=data.bare.states.find(s=>s.id===key);let slot=5;for(let i=0;i<6;i++){if(e<s.frameDurationsMs[i]){slot=i;break}e-=s.frameDurationsMs[i]}return [key,slot]}function draw(){const [key,slot]=selection();phase=slot;ctx.fillStyle=bg.value;ctx.fillRect(0,0,1024,700);ctx.fillStyle='#e5ebed';ctx.font='16px sans-serif';for(let j=0;j<2;j++){const g=j?'helmet':'bare',im=images[g][key][slot];ctx.fillText(g+' / '+key+' / '+slot,8,j*350+22);for(const [r,x] of [[148,128],[82,350],[54,515],[27,650]]){const s=r/148;ctx.drawImage(im,x-128*s,j*350+170-128*s,256*s,256*s);ctx.fillText(r+'px ruler',x-45,j*350+285)}ctx.drawImage(im,62,87,75,70,775,j*350+50,225,210);ctx.fillText('head / shoulder / grip',770,j*350+285)}clock.textContent=Math.round(elapsed)+'ms';document.getElementById('phase').value=slot}function tick(t){if(running){const length=clip.value==='chain'?2200:clip.value==='salvage-west'?840:1000;elapsed=(elapsed+(t-last)*Number(speed.value))%length}last=t;draw();requestAnimationFrame(tick)}play.onclick=()=>{running=!running;play.textContent=running?'Pause':'Play'};clip.onchange=()=>{elapsed=0};document.getElementById('phase').oninput=e=>{running=false;play.textContent='Play';if(clip.value==='chain')clip.value='swim-pickup-west';const s=data.bare.states.find(s=>s.id===clip.value);elapsed=s.frameDurationsMs.slice(0,Number(e.target.value)).reduce((a,b)=>a+b,0);draw()};init()</script>'''
